          <input type='checkbox' id='attestation' name='attestation' required aria-required='true'>
          <label for='attestation'>I confirm that the member and plan details shown above, as pre-populated from the policy record, are accurate and complete to the best of my knowledge, that I have reported any discrepancy to my payroll team, and that I am authorised by the plan sponsor to submit this disability claim on the member&rsquo;s behalf.</label>
        </div>
        <div class='err-box' id='attest-error' role='alert'></div>
      </div>
    </section>

    <div class='actions'>
      <p class='note'>Submitting sends one associated packet to MapleSure intake and returns your reference immediately.</p>
      <button type='submit' class='btn btn-primary' id='submit-btn'>Submit claim</button>
    </div>
  </form>

  <section id='confirmation' hidden aria-live='polite'>
    <div class='conf-head'>
      <div class='tick'>&#10003;</div>
      <div>
        <h2>Claim submitted to MapleSure intake</h2>
        <p class='conf-sub' id='conf-sub'></p>
      </div>
    </div>

    <p style='margin:18px 0 0'><span class='staged' id='conf-staged-badge'>Staged &middot; demo output</span></p>
    <div class='staged-note' id='conf-staged-note'>This confirmation is <strong>staged demo output</strong>. Nothing is sent, stored or indexed: the reference number is generated in the browser, no record exists in any MapleSure system, and the status and next steps below describe how the live service would behave, not something that has happened.</div>

    <div class='ref'>
      <dl class='kv'>
        <div>
          <dt>Reference number</dt>
          <dd class='refno' id='reference-number'></dd>
        </div>
        <div>
          <dt>Status</dt>
          <dd><span class='pill' id='status-text'>Received</span></dd>
        </div>
        <div>
          <dt>Submitted</dt>
          <dd id='conf-timestamp'></dd>
        </div>
        <div>
          <dt>Documents in packet</dt>
          <dd id='conf-docs'></dd>
        </div>
      </dl>
    </div>

    <dl class='kv' id='conf-kv'></dl>

    <ol class='next'>
      <li>Quote the reference number above in any call or email about this claim. <em>(Staged: the reference exists only in this browser session.)</em></li>
      <li>Intake would index the packet and confirm whether anything further is required. <em>(Staged: no packet is transmitted.)</em></li>
      <li>Progress would be tracked under Claims &rsaquo; Submission status in SponsorConnect. <em>(Staged: that screen is not part of this demo.)</em></li>
    </ol>

    <div class='conf-actions'>
      <button type='button' class='btn btn-secondary' id='print-btn'>Print this confirmation</button>
      <button type='button' class='btn btn-secondary' id='another-btn'>Submit another claim</button>
    </div>
  </section>
</main>

<footer class='site'>
  <div class='wrap foot'>
    <span>MapleSure Insurance — fictional demo application</span>
    <span>SponsorConnect &middot; Group Disability &middot; v0.1</span>
  </div>
</footer>

<script>
(function(){
  var MEMBERS = {
    'GRP-448120|M-10093': {
      'Member name': 'Dana R. Whitfield',
      'Date of birth': '1984-03-11',
      'Member id': 'M-10093',
      'Occupation': 'Line Supervisor, Assembly',
      'Division': 'Northbridge Manufacturing — Plant 2',
      'Hire date': '2016-09-06',
      'Plan': 'Group Long-Term Disability — Class A',
      'Coverage status': 'Active'
    },
    'GRP-448120|M-10154': {
      'Member name': 'Sanjay Balakrishnan',
      'Date of birth': '1991-07-28',
      'Member id': 'M-10154',
      'Occupation': 'Quality Analyst',
      'Division': 'Northbridge Manufacturing — Plant 1',
      'Hire date': '2020-02-18',
      'Plan': 'Group Long-Term Disability — Class B',
      'Coverage status': 'Active'
    },
    'GRP-771003|M-20488': {
      'Member name': 'Marie-Claude Tremblay',
      'Date of birth': '1978-11-02',
      'Member id': 'M-20488',
      'Occupation': 'Regional Account Manager',
      'Division': 'Cedarline Logistics — East',
      'Hire date': '2011-05-30',
      'Plan': 'Group Short-Term Disability — Class A',
      'Coverage status': 'Active'
    }
  };

  var ALLOWED = ['pdf','jpg','jpeg','png','doc','docx'];
  var MAX_BYTES = 10 * 1024 * 1024;

  var CLAIM_FIELDS = [
    { id: 'last-day-worked', label: 'Last day worked' },
    { id: 'first-day-absent', label: 'First day absent' },
    { id: 'nature-of-absence', label: 'Nature of absence' },
    { id: 'absence-details', label: 'Details for intake' }
  ];

  var form = document.getElementById('claim-form');
  var lookupBtn = document.getElementById('lookup-btn');
  var lookupMsg = document.getElementById('lookup-msg');
  var memberPanel = document.getElementById('member-details');
  var memberKv = document.getElementById('member-kv');
  var docsInput = document.getElementById('documents');
  var fileList = document.getElementById('file-list');
  var fileEmpty = document.getElementById('file-empty');
  var fileError = document.getElementById('file-error');
  var claimError = document.getElementById('claim-error');
  var attestBox = document.getElementById('attestation');
  var attestError = document.getElementById('attest-error');
  var confirmation = document.getElementById('confirmation');

  var currentMember = null;
  var attached = [];

  function renderKv(target, record){
    target.innerHTML = '';
    Object.keys(record).forEach(function(key){
      var value = record[key];
      var long = typeof value === 'string' && value.length > 60;
      var wrap = document.createElement('div');
      var dt = document.createElement('dt');
      var dd = document.createElement('dd');
      if(long){ wrap.className = 'full'; dd.className = 'long'; }
      dt.textContent = key;
      dd.textContent = value;
      wrap.appendChild(dt);
      wrap.appendChild(dd);
      target.appendChild(wrap);
    });
  }

  function lookupMember(){
    var policy = document.getElementById('policy-number').value.trim().toUpperCase();
    var member = document.getElementById('member-id').value.trim().toUpperCase();

    if(!policy || !member){
      currentMember = null;
      memberPanel.hidden = true;
      lookupMsg.className = 'msg err';
      lookupMsg.textContent = 'Enter both a policy number and a member id, then look up the member.';
      return;
    }

    var record = MEMBERS[policy + '|' + member];
    if(!record){
      currentMember = null;
      memberPanel.hidden = true;
      lookupMsg.className = 'msg err';
      lookupMsg.textContent = 'No covered member found for policy ' + policy + ' and member id ' + member + '. Check the values, or try GRP-448120 with M-10093.';
      return;
    }

    currentMember = record;
    renderKv(memberKv, record);
    memberPanel.hidden = false;
    lookupMsg.className = 'msg ok';
    lookupMsg.textContent = 'Member found on policy ' + policy + '. Details pre-populated below for your confirmation.';
  }

  function formatSize(bytes){
    if(bytes < 1024){ return bytes + ' B'; }
    if(bytes < 1024 * 1024){ return (bytes / 1024).toFixed(0) + ' KB'; }
    return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
  }

  function extensionOf(name){
    var dot = name.lastIndexOf('.');
    return dot === -1 ? '' : name.slice(dot + 1).toLowerCase();
  }

  function clearAttachments(){
    attached = [];
    docsInput.value = '';
    fileList.innerHTML = '';
    fileEmpty.style.display = '';
  }

  function renderAttachments(){
    fileList.innerHTML = '';
    attached.forEach(function(file){
      var li = document.createElement('li');
      var name = document.createElement('span');
      var size = document.createElement('span');
      name.textContent = file.name;
      size.className = 'sz';
      size.textContent = formatSize(file.size);
      li.appendChild(name);
      li.appendChild(size);
      fileList.appendChild(li);
    });
    fileEmpty.style.display = attached.length ? 'none' : '';
  }

  function handleFiles(){
    fileError.style.display = 'none';
    fileError.textContent = '';

    var picked = Array.prototype.slice.call(docsInput.files || []);
    if(!picked.length){
      clearAttachments();
      return;
    }

    var rejected = [];
    picked.forEach(function(file){
      var ext = extensionOf(file.name);
      if(ALLOWED.indexOf(ext) === -1){
        rejected.push(file.name + ' — file type .' + (ext || 'unknown') + ' is not accepted');
      } else if(file.size > MAX_BYTES){
        rejected.push(file.name + ' — ' + formatSize(file.size) + ' exceeds the 10 MB limit');
      }
    });

    if(rejected.length){
      clearAttachments();
      fileError.style.display = 'block';
      fileError.textContent = 'Nothing was attached. ' + rejected.join('; ') + '. Accepted types are PDF, JPG, PNG, DOC and DOCX, up to 10 MB each. Choose your documents again.';
      return;
    }

    attached = picked;
    renderAttachments();
  }

  function valueOf(id){
    return (document.getElementById(id).value || '').trim();
  }

  function markField(id, ok){
    var wrap = document.getElementById('field-' + id);
    if(!wrap){ return; }
    if(ok){ wrap.classList.remove('invalid'); }
    else { wrap.classList.add('invalid'); }
  }

  function validateClaimDetails(){
    var missing = [];
    CLAIM_FIELDS.forEach(function(field){
      var ok = valueOf(field.id) !== '';
      markField(field.id, ok);
      if(!ok){ missing.push(field.label); }
    });

    if(missing.length){
      claimError.style.display = 'block';
      claimError.textContent = 'Intake cannot open a file without the absence information. Complete ' +
        (missing.length === 1 ? 'this field' : 'these fields') + ': ' + missing.join(', ') + '.';
      return false;
    }

    claimError.style.display = 'none';
    claimError.textContent = '';
    return true;
  }

  function firstMissingClaimField(){
    for(var i = 0; i < CLAIM_FIELDS.length; i++){
      if(valueOf(CLAIM_FIELDS[i].id) === ''){
        return document.getElementById(CLAIM_FIELDS[i].id);
      }
    }
    return null;
  }

  function pad(value, width){
    var text = String(value);
    while(text.length < width){ text = '0' + text; }
    return text;
  }

  function makeReference(when, sequence){
    var stamp = when.getFullYear() + '-' + pad(when.getMonth() + 1, 2) + '-' +
      pad(when.getDate(), 2) + pad(when.getHours(), 2) + pad(when.getMinutes(), 2) +
      pad(when.getSeconds(), 2);
    return 'MS-' + stamp + '-' + pad(sequence, 3);
  }

  var submissionCount = 0;

  function showConfirmation(){
    var when = new Date();
    submissionCount = submissionCount + 1;
    var reference = makeReference(when, submissionCount);
    var nature = valueOf('nature-of-absence');
    var lastDay = valueOf('last-day-worked');
    var firstAbsent = valueOf('first-day-absent');
    var details = valueOf('absence-details');

    document.getElementById('reference-number').textContent = reference;
    document.getElementById('status-text').textContent = 'Received';
    document.getElementById('conf-timestamp').textContent = when.toLocaleString();
    document.getElementById('conf-docs').textContent = attached.length === 1 ? '1 document' : attached.length + ' documents';
    document.getElementById('conf-sub').textContent = 'Staged demo confirmation — one packet for ' + currentMember['Member name'] + ' would be sent to MapleSure intake for indexing under the reference below.';

    renderKv(document.getElementById('conf-kv'), {
      'Member': currentMember['Member name'],
      'Member id': currentMember['Member id'],
      'Plan': currentMember['Plan'],
      'Nature of absence': nature,
      'Last day worked': lastDay,
      'First day absent': firstAbsent,
      'Details for intake': details
    });

    form.hidden = true;
    document.getElementById('steps').hidden = true;
    document.getElementById('page-title').textContent = 'Claim submitted';
    document.getElementById('page-lede').textContent = 'Keep the reference number below. It identifies this submission and every document attached to it. This is staged demo output — no claim has actually been transmitted.';
    confirmation.hidden = false;
    window.scrollTo(0, 0);
  }

  lookupBtn.addEventListener('click', lookupMember);
  docsInput.addEventListener('change', handleFiles);

  CLAIM_FIELDS.forEach(function(field){
    var element = document.getElementById(field.id);
    element.addEventListener('change', function(){
      if(valueOf(field.id) !== ''){ markField(field.id, true); }
    });
    element.addEventListener('input', function(){
      if(valueOf(field.id) !== ''){ markField(field.id, true); }
    });
  });

  attestBox.addEventListener('change', function(){
    if(attestBox.checked){
      attestError.style.display = 'none';
    }
  });

  form.addEventListener('submit', function(event){
    event.preventDefault();

    if(!currentMember){
      lookupMsg.className = 'msg err';
      lookupMsg.textContent = 'Look up the member before submitting, so the claim is filed against the right policy.';
      document.getElementById('policy-number').focus();
      window.scrollTo(0, 0);
      return;
    }

    if(!validateClaimDetails()){
      var target = firstMissingClaimField();
      if(target){ target.focus(); }
      return;
    }

    if(!attestBox.checked){
      attestError.style.display = 'block';
      attestError.textContent = 'Confirm the member and plan details are accurate before the submission can be accepted.';
      attestBox.focus();
      return;
    }

    attestError.style.display = 'none';
    showConfirmation();
  });

  document.getElementById('print-btn').addEventListener('click', function(){
    window.print();
  });

  document.getElementById('another-btn').addEventListener('click', function(){
    window.location.reload();
  });
})();
</script>
</body>
</html>
"}]}
